# gf2lib.py -- review-computation helpers written for TASK-20260924-a2c79b.
# Own code. Binary-field arithmetic, F_2[X] polynomials as Python ints
# (bit i = coefficient of X^i), and affine arithmetic on
# y^2 + xy = x^3 + a x^2 + b over F_{2^n}. No library beyond the stdlib.
import random


# ---------------------------------------------------------------- F_2[X]
def pdeg(f):
    return f.bit_length() - 1


def pmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r


def pmod(a, m):
    dm = pdeg(m)
    while a and pdeg(a) >= dm:
        a ^= m << (pdeg(a) - dm)
    return a


def pdivmod(a, m):
    q = 0
    dm = pdeg(m)
    while a and pdeg(a) >= dm:
        s = pdeg(a) - dm
        q ^= 1 << s
        a ^= m << s
    return q, a


def pgcd(a, b):
    while b:
        a, b = b, pmod(a, b)
    return a


def is_irreducible(f):
    """Brute force: no factor of degree 1..deg(f)//2."""
    d = pdeg(f)
    for g in range(2, 1 << (d // 2 + 1)):
        if pdeg(g) >= 1 and pdeg(g) <= d // 2 and pmod(f, g) == 0:
            return False
    return True


def lowest_weight_irreducible(n):
    """Lowest weight, then lexicographically (integer) least, monic, deg n."""
    for w in range(3, n + 2, 2):  # irreducible => odd weight (f(1)=1) and constant 1
        cands = []
        from itertools import combinations
        for mids in combinations(range(1, n), w - 2):
            f = (1 << n) | 1
            for i in mids:
                f |= 1 << i
            cands.append(f)
        for f in sorted(cands):
            if is_irreducible(f):
                return f
    raise ValueError


def factor_F2(f):
    """Full factorisation over F_2 by trial division (small degrees only)."""
    out = []
    g = 2
    while pdeg(f) > 0:
        if pdeg(g) > pdeg(f):
            break
        q, r = pdivmod(f, g)
        if r == 0 and is_irreducible(g):
            out.append(g)
            f = q
        else:
            g += 1
    return sorted(out)


def ptostr(f):
    terms = []
    for i in range(pdeg(f), -1, -1):
        if (f >> i) & 1:
            terms.append('1' if i == 0 else ('X' if i == 1 else 'X^%d' % i))
    return ' + '.join(terms) if terms else '0'


# ---------------------------------------------------------------- F_{2^n}
class GF2n:
    def __init__(self, n, modpoly):
        self.n = n
        self.m = modpoly

    def mul(self, a, b):
        return pmod(pmul(a, b), self.m)

    def sq(self, a):
        return self.mul(a, a)

    def pow(self, a, e):
        r = 1
        while e:
            if e & 1:
                r = self.mul(r, a)
            a = self.sq(a)
            e >>= 1
        return r

    def inv(self, a):
        assert a != 0
        return self.pow(a, (1 << self.n) - 2)

    def tr(self, a):
        t = a
        s = a
        for _ in range(self.n - 1):
            s = self.sq(s)
            t ^= s
        assert t in (0, 1)
        return t

    def halftrace(self, c):
        # n odd: H(c) = sum_{i=0}^{(n-1)/2} c^(2^(2i)); z^2 + z = c + Tr(c)
        assert self.n % 2 == 1
        z = c
        s = c
        for _ in range((self.n - 1) // 2):
            s = self.sq(self.sq(s))
            z ^= s
        return z


# ---------------------------------------------------------------- curve
O = None


class Curve:
    """y^2 + xy = x^3 + a x^2 + b over F_{2^n}."""

    def __init__(self, F, a, b):
        self.F, self.a, self.b = F, a, b

    def on(self, P):
        if P is O:
            return True
        F = self.F
        x, y = P
        lhs = F.sq(y) ^ F.mul(x, y)
        rhs = F.mul(F.sq(x), x) ^ F.mul(self.a, F.sq(x)) ^ self.b
        return lhs == rhs

    def neg(self, P):
        if P is O:
            return O
        x, y = P
        return (x, x ^ y)

    def add(self, P, Q):
        F = self.F
        if P is O:
            return Q
        if Q is O:
            return P
        x1, y1 = P
        x2, y2 = Q
        if x1 == x2:
            if y1 ^ y2 == x1:  # Q = -P (covers x1 = 0 doubling of 2-torsion)
                return O
            return self.dbl(P)
        lam = F.mul(y1 ^ y2, F.inv(x1 ^ x2))
        x3 = F.sq(lam) ^ lam ^ x1 ^ x2 ^ self.a
        y3 = F.mul(lam, x1 ^ x3) ^ x3 ^ y1
        return (x3, y3)

    def dbl(self, P):
        F = self.F
        if P is O:
            return O
        x1, y1 = P
        if x1 == 0:
            return O
        lam = x1 ^ F.mul(y1, F.inv(x1))
        x3 = F.sq(lam) ^ lam ^ self.a
        y3 = F.sq(x1) ^ F.mul(lam ^ 1, x3)
        return (x3, y3)

    def mul(self, k, P):
        if k < 0:
            return self.mul(-k, self.neg(P))
        R = O
        A = P
        while k:
            if k & 1:
                R = self.add(R, A)
            A = self.dbl(A)
            k >>= 1
        return R

    def frob(self, P):
        if P is O:
            return O
        return (self.F.sq(P[0]), self.F.sq(P[1]))

    def lift_x(self, x):
        """Return a point with this x, or None."""
        F = self.F
        if x == 0:
            # y^2 = b -> y = b^(2^(n-1))
            return (0, F.pow(self.b, 1 << (F.n - 1)))
        c = x ^ self.a ^ F.mul(self.b, F.inv(F.sq(x)))
        if F.tr(c) != 0:
            return None
        z = F.halftrace(c)
        y = F.mul(x, z)
        P = (x, y)
        assert self.on(P)
        return P


def lucas_order(n, a):
    t = 1 if a == 1 else -1
    s_prev, s = 2, t
    for _ in range(n - 1):
        s_prev, s = s, t * s - 2 * s_prev
    return (1 << n) + 1 - s, s

