# rank_checks.py -- REVIEW COMPUTATION for TASK-20260924-a2c79b, J1 attacks
# (i) and (iii). Re-derives the contract's rank statements on PLANTED matrices
# over F_r with two independent rank routines (own Gaussian elimination;
# sympy DomainMatrix over GF(p)), against the evaluation count EVAL of lemma
# L3. Parameters: the fixture prime r = 65587, k = 17, lambda = 17184, plus
# planted primes p = 1 mod 17 at which the 0/1 lift of an F_2-factor of Phi_17
# has a root in mu_17 (so that h_g is nontrivial). No curve relation is
# generated here except the L4-converse witness at the end, which uses the
# fixture curve with the full field as W. Mints no RUN-*.
import json, random, itertools
import sympy
from sympy.polys.matrices import DomainMatrix
from sympy import GF as sGF, symbols, Poly, resultant, ZZ
from gf2lib import *

random.seed(1787420)
OUT = {}


# ------------------------------------------------------------ rank routines
def rank_own(M, p):
    A = [[v % p for v in row] for row in M]
    rk, col = 0, 0
    rows, cols = len(A), (len(A[0]) if A else 0)
    for col in range(cols):
        piv = next((i for i in range(rk, rows) if A[i][col]), None)
        if piv is None:
            continue
        A[rk], A[piv] = A[piv], A[rk]
        inv = pow(A[rk][col], -1, p)
        A[rk] = [v * inv % p for v in A[rk]]
        for i in range(rows):
            if i != rk and A[i][col]:
                f = A[i][col]
                A[i] = [(u - f * v) % p for u, v in zip(A[i], A[rk])]
        rk += 1
    return rk


def rank_sympy(M, p):
    K = sGF(p)
    return DomainMatrix([[K(v % p) for v in row] for row in M], (len(M), len(M[0])), K).rank()


# ------------------------------------------------------------ F_p[X] helpers (lists, low->high)
def polymulmod_Xk(f, j, k, p):
    """X^j f(X) mod (X^k - 1), f of length k."""
    return [f[(e - j) % k] % p for e in range(k)]


def polyrem(a, h, p):
    """a mod h over F_p; h monic, lists low->high."""
    a = [v % p for v in a]
    dh = len(h) - 1
    for i in range(len(a) - 1, dh - 1, -1):
        c = a[i]
        if c:
            for t in range(dh + 1):
                a[i - dh + t] = (a[i - dh + t] - c * h[t]) % p
    return a[:dh] if dh > 0 else []


def poly_from_roots(roots, p):
    h = [1]
    for z in roots:
        h = [((h[i - 1] if i > 0 else 0) - z * (h[i] if i < len(h) else 0)) % p for i in range(len(h) + 1)]
    return h


def peval(f, z, p):
    return sum(c * pow(z, i, p) for i, c in enumerate(f)) % p


def family_matrix(fs, h, k, p):
    """Rows j = 0..k-1: concatenation over orbits O of (X^j f_O mod (X^k-1)) mod h."""
    M = []
    for j in range(k):
        row = []
        for f in fs:
            g = polymulmod_Xk(f, j, k, p)
            row += polyrem(g, h, p) if len(h) > 1 else []
        M.append(row if row else [0])
    return M


def EVAL(fs, hroots, p):
    return sum(1 for z in hroots if any(peval(f, z, p) for f in fs))


def check(fs, hroots, k, p):
    h = poly_from_roots(hroots, p)
    M = family_matrix(fs, h, k, p)
    a, b = rank_own(M, p), rank_sympy(M, p)
    return {'rank_own': a, 'rank_sympy': b, 'EVAL': EVAL(fs, hroots, p), 'agree': a == b == EVAL(fs, hroots, p)}


# ------------------------------------------------------------ fixture parameters
r, k, lam = 65587, 17, 17184
mu = [pow(lam, i, r) for i in range(k)]
assert len(set(mu)) == k and pow(lam, k, r) == 1
RAW, QUO = mu, [lam]

# (1) CTL-PLANTED (i): U diag(I_rho,0) V, shape k x 4k, rho in {1, 8, 9, 17}
def rand_invertible(n, p):
    while True:
        A = [[random.randrange(p) for _ in range(n)] for _ in range(n)]
        if rank_own(A, p) == n:
            return A


def matmul(A, B, p):
    return [[sum(a * b for a, b in zip(row, col)) % p for col in zip(*B)] for row in A]


planted = {}
for rho in [1, 8, 9, 17]:
    res = []
    for _ in range(20):
        U = rand_invertible(k, r)
        V = rand_invertible(4 * k, r)
        D = [[1 if (i == j and i < rho) else 0 for j in range(4 * k)] for i in range(k)]
        M = matmul(matmul(U, D, r), V, r)
        res.append((rank_own(M, r), rank_sympy(M, r)))
    planted[rho] = {'all_equal_rho': all(a == b == rho for a, b in res), 'n': len(res)}
OUT['ctl_planted_i'] = planted

# (2) CTL-PLANTED (ii): structured orbit polynomials through raw, quotient, ker-g (planted h)
def coeffs_from_roots_padded(roots, k, p):
    c = poly_from_roots(roots, p)
    return c + [0] * (k - len(c))


z0 = mu[3]
S = mu[1:9]  # |S| = n' = 8
struct = {
    'f=1': [1] + [0] * (k - 1),
    'f=(X^k-1)/(X-z0)': coeffs_from_roots_padded([z for z in mu if z != z0], k, r),
    "f=prod_{z not in S}(X-z), |S|=8": coeffs_from_roots_padded([z for z in mu if z not in S], k, r),
}
planted_h = [mu[0], mu[3], mu[5], mu[12]]  # a planted h dividing X^k - 1
struct_res = {}
for name, f in struct.items():
    struct_res[name] = {'raw': check([f], RAW, k, r), 'quotient': check([f], QUO, k, r),
                        'kerg_planted_h': check([f], planted_h, k, r)}
OUT['ctl_planted_ii'] = struct_res

# (3) L3 corollaries, class and point bases
cor = {}
for d in [1, 2, 5, 16]:
    e = 4
    fm = [0] * k; fm[e] += 1; fm[(e + d) % k] -= 1          # legs P, -tau^d P: class f = X^e (1 - X^d)
    fp = [0] * k; fp[e] += 1; fp[(e + d) % k] += 1          # legs P, +tau^d P: class f = X^e (1 + X^d)
    pt1 = [0] * k; pt1[e] = 1                                # point basis: P in orbit A
    pt2 = [0] * k; pt2[(e + d) % k] = 1                      # -tau^d P lies in a different point orbit (L2)
    cor['d=%d' % d] = {
        'minus_class_raw': check([fm], RAW, k, r), 'minus_point_raw': check([pt1, pt2], RAW, k, r),
        'plus_class_raw': check([fp], RAW, k, r), 'plus_point_raw': check([fp], RAW, k, r),
        'minus_quotient': check([fm], QUO, k, r), 'plus_quotient': check([fp], QUO, k, r)}
OUT['L3_corollaries'] = cor

# (4) random multi-orbit relations with small integer coefficients, and adversarial ones
rnd = {'raw': 0, 'quotient': 0, 'kerg_planted': 0, 'disagreements': []}
for trial in range(300):
    nO = random.randint(1, 4)
    fs = []
    for _ in range(nO):
        f = [0] * k
        for _ in range(random.randint(1, 3)):
            f[random.randrange(k)] += random.choice([1, -1])
        fs.append(f)
    for basis, hroots in [('raw', RAW), ('quotient', QUO), ('kerg_planted', planted_h)]:
        c = check(fs, hroots, k, r)
        rnd[basis] += 1
        if not c['agree']:
            rnd['disagreements'].append((basis, fs, c))
# adversarial: f vanishing at chosen roots
adv = []
for Z in [[lam], [mu[1], mu[2]], mu[:10], mu[1:]]:
    f = coeffs_from_roots_padded(Z, k, r)
    for basis, hroots in [('raw', RAW), ('quotient', QUO), ('kerg_planted', planted_h)]:
        c = check([f], hroots, k, r)
        adv.append({'zeros_at': len(Z), 'basis': basis, **c})
rnd['adversarial'] = adv
OUT['L3_random_and_adversarial'] = rnd

# (5) ker-g basis exactly as defined, with a NONTRIVIAL h_g on a planted prime.
# kerg_search.py shows Res(g-hat, Phi_17) has no prime factor = 1 mod 17 for any of the four
# n = 17 divisors, so the planted setting uses n = 23, g = its canonical f1, and p = 47
# (47 = 1 mod 23 divides Res(f1-hat, Phi_23)).
x = symbols('x')
KK, p = 23, 47
g23 = 0b101011100011
gen = sympy.primitive_root(p)
lam_p = pow(gen, (p - 1) // KK, p)
mu_p = [pow(lam_p, i, p) for i in range(KK)]
assert len(set(mu_p)) == KK


def lift_eval(bits, z, q):
    return sum(pow(z, i, q) for i in range(pdeg(bits) + 1) if (bits >> i) & 1) % q


def bits_to_sym(b):
    return sum(x ** i for i in range(pdeg(b) + 1) if (b >> i) & 1)


hg_roots = [z for z in mu_p if lift_eval(g23, z, p) == 0]
kg = {'n_k': KK, 'p': p, 'g_bits': bin(g23), 'lambda_p': lam_p, 'h_g_roots': hg_roots, 'deg_h_g': len(hg_roots)}
G = Poly(bits_to_sym(g23), x, modulus=p)
Xk = Poly(x ** KK - 1, x, modulus=p)
gg = G.gcd(Xk)
kg['sympy_gcd_degree'] = gg.degree()
kg['h_g_equals_sympy_gcd'] = (gg.degree() == len(hg_roots)) and all(int(gg.eval(z)) % p == 0 for z in hg_roots)
agree = []
for trial in range(200):
    fs = []
    for _ in range(random.randint(1, 3)):
        f = [0] * KK
        for _ in range(random.randint(1, 3)):
            f[random.randrange(KK)] += random.choice([1, -1])
        fs.append(f)
    agree.append(check(fs, hg_roots, KK, p)['agree'])
kg['random_relations_all_agree_with_EVAL'] = all(agree)
kg['n_random_relations'] = len(agree)
# planted relation hitting the h_g root: f = 1 (monomial) -> rank = deg h_g
kg['monomial_relation'] = check([[1] + [0] * (KK - 1)], hg_roots, KK, p)
# class-vs-point contrast: three legs in three different POINT orbits that merge into ONE
# class orbit with signs (+,+,-) and shifts (0, a, c): class f = 1 + X^a - X^c.
contrast = None
for a_, c_ in itertools.product(range(1, KK), range(1, KK)):
    fcls = [0] * KK; fcls[0] += 1; fcls[a_] += 1; fcls[c_] -= 1
    if any(v % p for v in fcls) and any(peval(fcls, z, p) == 0 for z in hg_roots):
        pts = []
        for s_ in [0, a_, c_]:
            m_ = [0] * KK; m_[s_] = 1; pts.append(m_)
        contrast = {'a': a_, 'c': c_, 'kerg_class_reading': check([fcls], hg_roots, KK, p),
                    'kerg_point_reading': check(pts, hg_roots, KK, p),
                    'raw_class': check([fcls], mu_p, KK, p), 'raw_point': check(pts, mu_p, KK, p)}
        break
kg['class_vs_point_contrast_m3'] = contrast
kg['ghat_at_1_is_weight'] = lift_eval(g23, 1, p)
OUT['kerg_nontrivial_planted'] = kg


# (6) L4 converse witness on the fixture curve: a relation with pi_G(R) = O whose quotient rank is 1
n, a, b = 17, 1, 1
F = GF2n(n, lowest_weight_irreducible(n))
E = Curve(F, a, b)
hcof = 2


def piG(P):
    return E.mul(hcof * pow(hcof, -1, r), P)


def classcol(Q):
    """Return (orbit id, e, eps) with the contract's convention: Q = eps [lam^e] Q_O,
    Q_O the element of the orbit {+-[lam^e]Q} with least x, sign tie broken by least y."""
    orbit = []
    for e in range(k):
        Qe = E.mul(pow(lam, e, r), Q)
        orbit += [Qe, E.neg(Qe)]
    QO = min(orbit, key=lambda P: (P[0], P[1]))
    for e in range(k):
        base = E.mul(pow(lam, e, r), QO)
        if base == Q:
            return (QO, e, 1)
        if E.neg(base) == Q:
            return (QO, e, -1)
    raise RuntimeError


T = (0, 1)
wit = None
for attempt in range(50):
    P1 = E.lift_x(random.randrange(2, 1 << n))
    P2 = E.lift_x(random.randrange(2, 1 << n))
    if P1 is None or P2 is None:
        continue
    P3 = E.add(T, E.neg(E.add(P1, P2)))  # P1 + P2 + P3 = T
    if P3 is O or any(piG(P) is O for P in (P1, P2, P3)):
        continue
    cols = [classcol(piG(P)) for P in (P1, P2, P3)]
    if len({c[0] for c in cols}) < 3:
        continue
    fs = []
    for (QO, e, eps) in cols:
        f = [0] * k; f[e] = eps; fs.append(f)
    R = E.add(E.add(P1, P2), P3)
    wit = {'R_equals_T': R == T, 'R_ne_O': R is not O, 'piG_R_is_O': piG(R) is O,
           'distinct_class_orbits': 3, 'quotient_rank': check(fs, QUO, k, r),
           'raw_class_rank': check(fs, RAW, k, r)}
    break
OUT['L4_converse_witness'] = wit
# and the H-statement literal reading 'target not O': legs P, T - P with R = T
xx = 12345
while E.lift_x(xx) is None or piG(E.lift_x(xx)) is O:
    xx += 1
P = E.lift_x(xx)
P2 = E.add(T, E.neg(P))
c1, c2 = classcol(piG(P)), classcol(piG(P2))
f = [0] * k
f[c1[1]] += c1[2]
if c2[0] == c1[0]:
    f[c2[1]] += c2[2]
OUT['H_target_not_O_literal_witness'] = {'R_is_T_ne_O': E.add(P, P2) == T, 'same_class_orbit': c2[0] == c1[0],
                                         'class_f_is_zero': not any(v % r for v in f),
                                         'quotient_rank': check([f], QUO, k, r)['rank_own'],
                                         'raw_class_rank': check([f], RAW, k, r)['rank_own']}
print(json.dumps(OUT, indent=1, default=str))

